import {Badge,Empty,LocalNotice,PageHeading} from '../../components/ui';
import {loadWorkspace} from '../../lib/data';
export const dynamic='force-dynamic';
export default async function VendorsPage(){const w=await loadWorkspace();return <><PageHeading title="Vendors" subtitle="Verified vendor master records used for deterministic invoice resolution"/><LocalNotice enabled={w.enabled}/><div className="metrics-grid"><div className="metric"><div className="metric-label">VENDORS</div><div className="metric-value">{w.vendors.length}</div><div className="metric-note">In the connected workspace</div></div><div className="metric"><div className="metric-label">ACTIVE</div><div className="metric-value">{w.vendors.filter(v=>v.status==='ACTIVE').length}</div><div className="metric-note">Eligible for resolution</div></div><div className="metric"><div className="metric-label">WITH GSTIN</div><div className="metric-value">{w.vendors.filter(v=>v.gstin).length}</div><div className="metric-note">Strong tax identifier available</div></div></div><div className="table-panel">{w.vendors.length?<div className="table-scroll"><table className="data-table"><thead><tr><th>VENDOR</th><th>CODE</th><th>GSTIN</th><th>CURRENCY</th><th>STATUS</th></tr></thead><tbody>{w.vendors.map(v=><tr key={v.id}><td><strong>{v.display_name}</strong></td><td className="mono">{v.vendor_code}</td><td className="muted">{v.gstin??'—'}</td><td>{v.currency}</td><td><Badge label={v.status}/></td></tr>)}</tbody></table></div>:<Empty title="No vendors" message="Vendor records added to Supabase will appear here."/>}</div></>}
